// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 value, uint256 blockNum, uint256 time) public {
        // Assume admissible domain: value up to 100 ether, block number, and time reasonable
        vm.assume(value <= 100 ether);
        vm.assume(blockNum > 0);
        vm.assume(time > 1);
        vm.assume(time < type(uint256).max - 1);

        // Setup: ensure pastBlockTime is less than time to satisfy second require
        // We cannot set pastBlockTime directly, so we make a prior call to set it
        uint256 initialTime = time - 1;
        vm.warp(initialTime);
        // We need a prior call to set pastBlockTime; we call with 10 ether to pass original require
        // But the buggy version requires 0 ether, so we use a helper that calls with 10 ether only for setup?
        // Actually, we can use a distinguishable value that the fuzzer can vary. We'll use vm.prank and value.
        // For the reference, the require is msg.value == 10 ether. We must call with 10 ether to set pastBlockTime.
        // For the buggy version, same call will revert. But we need both to have pastBlockTime < time.
        // So we use a setup call that only succeeds on reference, then we test. Buggy will still have pastBlockTime = 0.
        // That's fine: the buggy version can be tested with pastBlockTime = 0.
        address caller = address(0x1234);
        vm.deal(caller, value + 100 ether); // ensure enough for value and potential 10 ether setup
        vm.prank(caller);
        try c.fallback{value: 10 ether}() {} catch {}

        // Now set block.timestamp and block.number for the test call
        vm.warp(time);
        vm.roll(blockNum);

        // Record balance before
        uint256 balanceBefore = address(c).balance;

        // Make the call with fuzzed value
        vm.deal(caller, value);
        vm.prank(caller);
        bool ok;
        try c.fallback{value: value}() { ok = true; } catch { ok = false; }

        uint256 balanceAfter = address(c).balance;

        // General rule: The contract's balance should not increase (should not gain funds)
        // after the fallback call. Since the fallback may transfer funds out, balanceAfter should be <= balanceBefore.
        assertTrue(balanceAfter <= balanceBefore);
    }
}

