    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, uint48 blockNum) public {
        amount = bound(amount, 0, 100 ether);
        vm.assume(blockNum % 15 != 0);
        vm.roll(blockNum);
        vm.warp(1);
        uint256 balBefore = address(c).balance;
        address sender = address(this);
        vm.deal(sender, amount);
        (bool ok,) = address(c).call{value: amount}("");
