pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, uint48 warpTime, uint256 blockNum) public {
        // Restrict to admissible domain: valid ETH amounts and realistic block parameters
        vm.assume(amount > 0 && amount <= 1000000 ether);
        vm.assume(warpTime > 0);
        vm.assume(blockNum % 15 == 0);

        // Setup: give the contract an initial balance and ensure the timestamp condition is satisfied
        vm.deal(address(c), 100 ether);
        vm.warp(warpTime);
        vm.roll(blockNum);

        uint256 balBefore = address(c).balance;
        address caller = address(0x1234);
        vm.deal(caller, amount);

        bool ok;
        vm.prank(caller);
        try c.fallback{value: amount}() {
            ok = true;
        } catch {
            ok = false;
        }

        // On the reference contract: the call succeeds, balance becomes 0,
        // and the caller receives the full pre-call balance.
        // The buggy version rejects this call (reverts) because it requires 0 ether.
        assertTrue(ok && address(c).balance == 0 && caller.balance == balBefore + amount - amount);
    }
}

