pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, uint256 blockNum, uint256 timestamp) public {
        vm.assume(amount <= 1000 ether);
        vm.assume(timestamp > 1);
        vm.assume(blockNum > 0);
        vm.assume(blockNum % 15 == 0);
        vm.deal(address(this), amount);
        vm.roll(blockNum);
        vm.warp(timestamp);
        // force pastBlockTime to be non-zero to test the timestamp guard
        vm.deal(address(this), 10 ether);
        vm.roll(1);
        vm.prank(address(this));
        (bool okInit,) = address(c).call{value: 10 ether}("");
        okInit;
        uint256 balBefore = address(c).balance;
        vm.roll(blockNum);
        vm.warp(timestamp + 1);
        vm.prank(address(this));
        (bool success,) = address(c).call{value: amount}("");
        if (success) {
            uint256 balAfter = address(c).balance;
            if (amount == 10 ether) {
                assertTrue(balAfter == 0);
            } else {
                // call succeeded but the fallback may have transferred or not;
                // the property is that the balance loss should not exceed msg.value
                // unless a transfer happens, but the reference will revert for wrong value.
                // We just leave the assert true for reference; the bug fails when amount=0.
                assertTrue(balAfter == balBefore - amount);
            }
        } else {
            assertTrue(balBefore == address(c).balance);
        }
    }
}

