pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint64 blockNum, uint64 timestamp) public {
        vm.assume(timestamp > 0);
        vm.assume(blockNum < type(uint64).max - 1);
        vm.roll(blockNum);
        vm.warp(timestamp);

        address actor = address(0x1000);
        vm.deal(actor, 20 ether);
        vm.prank(actor);
        c.fallback{value: 10 ether}();

        // Reference requires block.timestamp > pastBlockTime, so second call in same block must revert.
        // Mutant lacks the require, so it succeeds.
        bool secondCallReverted = false;
        vm.prank(actor);
        try c.fallback{value: 10 ether}() {
            secondCallReverted = false;
        } catch {
            secondCallReverted = true;
        }

        // After the first call, pastBlockTime equals current block.timestamp on both (unless the first call somehow failed).
        // The reference rule: if the second call did not revert (mutant behavior), then pastBlockTime is still equal to block.timestamp,
        // which contradicts the property that pastBlockTime should always be strictly less than block.timestamp when a call succeeds.
        // Since the reference always reverts the second call, the invariant holds: after any non-reverting fallback,
        // pastBlockTime < block.timestamp (because block.timestamp > pastBlockTime was enforced).
        bool refOk = (secondCallReverted == true) && (c.pastBlockTime() < block.timestamp);
        // But for the mutant, the second call succeeds and pastBlockTime ends up equal to block.timestamp,
        // breaking the strict inequality. Thus the invariant fails for the mutant when the fuzzer picks a timestamp > 0.
        assertTrue(refOk);
    }
}

