pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint160 actorSeed, uint256 blocksToAdvance) public {
        address actor = address(actorSeed);
        vm.assume(actor != address(0) && actor != address(c));
        vm.assume(blocksToAdvance > 0 && blocksToAdvance <= 100);

        vm.deal(actor, 20 ether);
        vm.roll(14); // block 14 -> block 15 is a multiple
        vm.warp(1);

        // First call in block 14
        vm.prank(actor);
        (bool ok1,) = address(c).call{value: 10 ether}("");
        require(ok1, "first call failed");

        // Advance block and time
        vm.roll(block.number + blocksToAdvance);
        vm.warp(block.timestamp + blocksToAdvance * 12);

        // Second call, possibly in same block as first if blocksToAdvance == 0 (but bounded >0)
        // Actually blocksToAdvance can be 1, so we are in a different block.
        vm.prank(actor);
        (bool ok2,) = address(c).call{value: 10 ether}("");
        require(ok2, "second call failed");

        // After two successful fallback calls, the balance should be 0
        // because at least one of them should have transferred everything out.
        // The reference ensures this because only one call can succeed per block,
        // and the transfer happens on multiples of 15.
        // With the bug, multiple calls can succeed without transferring on non-multiples,
        // leading to a non-zero balance if the second call is not on a multiple.
        assertEq(address(c).balance, 0);
    }
}

