pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 fuzzTimestamp, uint256 fuzzBlockNumber) public {
        // bound to reasonable ranges; keep wide enough to explore the space
        fuzzTimestamp = bound(fuzzTimestamp, 1, type(uint64).max);
        fuzzBlockNumber = bound(fuzzBlockNumber, 1, type(uint64).max);

        // set up the state: pastBlockTime must be less than fuzzTimestamp to pass the require
        // we warp and roll to the fuzzed values
        vm.warp(fuzzTimestamp);
        vm.roll(fuzzBlockNumber);

        // we need an actor with enough ether to trigger the fallback logic
        address actor = makeAddr("actor");
        vm.deal(actor, 100 ether);

        // Because the transfer happens conditionally, we record whether a transfer occurred.
        // We must ensure the fallback does not revert due to the transfer (the contract may have no balance).
        // We first give the contract some balance so the transfer can succeed if triggered.
        vm.deal(address(c), 1 ether);

        // We need to capture the balance of the actor before and after to detect the transfer.
        uint256 balanceBefore = actor.balance;

        vm.prank(actor);
        (bool success,) = address(c).call{value: 10 ether}("");
        require(success, "fallback reverted unexpectedly");

        uint256 balanceAfter = actor.balance;
        bool transferred = balanceAfter > balanceBefore;

        // General rule:
        // If a transfer occurred (i.e., the contract's balance was sent to sender),
        // then it MUST be that block.number % 15 == 0 (and implicitly not block.timestamp % 15 == 0).
        // The buggy version would trigger on block.timestamp % 15 == 0 regardless of block.number.
        // We assert: if transferred, then block.number % 15 == 0.
        // This holds for all admissible inputs on the reference, but fails on the buggy version
        // when block.timestamp % 15 == 0 and block.number % 15 != 0.
        assertTrue(!transferred || fuzzBlockNumber % 15 == 0, "Transfer occurred but not on block.number % 15 == 0");
    }
}

