        vm.warp(blockTime);
        vm.roll(blockNum);

        address sender = address(uint160(uint256(keccak256(abi.encode(seed)))));
        vm.deal(sender, 10 ether);
        vm.prank(sender);
        (bool ok,) = address(c).call{value: 10 ether}("");
        require(ok, "fallback failed");

        assertTrue(address(c).balance == 0);
    }
}
